using System;
using System.IO;
using UnityEngine;

namespace BrudvikWhiteHilt.TradingPosts;

/// <summary>
/// A trading post as generated by AssetSource/Preview/build_trading_post.py, the same script that draws the agreed
/// preview, so what the pictures show is what the mod builds. Positions are in post coordinates: the middle of the
/// landing at deck height, +z towards the sea.
/// </summary>
[Serializable]
public class TradingPostLayout
{
    private const string ResourceName = "BrudvikWhiteHilt.TradingPost.json";

    private static TradingPostLayout loaded;

    /// <summary>Where the layout comes from.</summary>
    public string note;

    /// <summary>The layout's version: posts built from an older one are built again.</summary>
    public int version;

    /// <summary>The middle of the jetty head (x, z), where a ship ties up.</summary>
    public float[] head;

    /// <summary>Where the trader stands.</summary>
    public TradingPostSpot trader;

    /// <summary>The protective dome.</summary>
    public TradingPostDomeData dome;

    /// <summary>Under the jetty: the tops of the long piles that go down to the bed where it lies deep.</summary>
    public TradingPostSpot[] piles;

    /// <summary>The ground levelled for the post.</summary>
    public TradingPostLevel[] level;

    /// <summary>The pieces of the post.</summary>
    public TradingPostPart[] parts;

    /// <summary>
    /// Loads the embedded layout once.
    /// </summary>
    /// <returns>The layout.</returns>
    public static TradingPostLayout Load()
    {
        if (loaded != null)
        {
            return loaded;
        }

        using Stream stream = typeof(TradingPostLayout).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' not found.");
        using StreamReader reader = new(stream);

        // Unity's JsonUtility leaves the mod's types empty in game; Jotunn's SimpleJson fills them by reflection.
        loaded = SimpleJson.SimpleJson.DeserializeObject<TradingPostLayout>(reader.ReadToEnd());
        if (loaded?.parts == null || loaded.parts.Length == 0 || loaded.dome == null)
        {
            throw new InvalidOperationException($"Embedded resource '{ResourceName}' has no parts or no dome.");
        }

        return loaded;
    }

    /// <summary>
    /// Turns three numbers from the layout into a vector.
    /// </summary>
    /// <param name="values">x, y and z.</param>
    /// <returns>The vector, or zero for a missing value.</returns>
    public static Vector3 ToVector(float[] values)
    {
        return values != null && values.Length >= 3 ? new Vector3(values[0], values[1], values[2]) : Vector3.zero;
    }
}

/// <summary>
/// One piece of a trading post.
/// </summary>
[Serializable]
public class TradingPostPart
{
    /// <summary>Prefab name.</summary>
    public string prefab;

    /// <summary>Position in post coordinates.</summary>
    public float[] position;

    /// <summary>Turn about y, in degrees.</summary>
    public float yaw;

    /// <summary>Stands on the ground where it is instead of at its height in the layout.</summary>
    public bool ground;
}

/// <summary>
/// A place in a trading post.
/// </summary>
[Serializable]
public class TradingPostSpot
{
    /// <summary>Position in post coordinates.</summary>
    public float[] position;

    /// <summary>Turn about y, in degrees.</summary>
    public float yaw;
}

/// <summary>
/// The protective dome over a trading post.
/// </summary>
[Serializable]
public class TradingPostDomeData
{
    /// <summary>Its centre in post coordinates.</summary>
    public float[] centre;

    /// <summary>Its radius in metres.</summary>
    public float radius;
}

/// <summary>
/// A round patch of ground levelled for a trading post, at its centre's height.
/// </summary>
[Serializable]
public class TradingPostLevel
{
    /// <summary>Centre in post coordinates; its y is the height the ground is levelled to.</summary>
    public float[] centre;

    /// <summary>Radius of the level ground, in metres.</summary>
    public float radius;

    /// <summary>Radius out to which the ground is smoothed into the land around, in metres.</summary>
    public float smooth;
}
